import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import * as YAML from 'yaml';

// 配置项类型
export interface ConfigItem {
  id: string;
  name: string;
  description: string;
  content: string;
  type: string;
  version: string;
  isDefault: boolean;
  favorite: boolean;
  createdAt: number;
  updatedAt: number;
}

// 配置快照类型
export interface ConfigSnapshot {
  id: string;
  name: string;
  content: string;
  timestamp: number;
}

// 配置状态接口
export interface ConfigState {
  currentConfig: string;
  configName: string;
  snapshots: ConfigSnapshot[];
  isValidYaml: boolean;
  yamlError: string | null;
  setCurrentConfig: (config: string) => void;
  setConfigName: (name: string) => void;
  saveSnapshot: () => void;
  loadSnapshot: (id: string) => void;
  deleteSnapshot: (id: string) => void;
  validateYaml: (content: string) => boolean;
}

// 默认配置模板
const DEFAULT_CONFIG = `qlib_init:
  provider_uri: "~/.qlib/qlib_data/cn_data"
  region: "cn"

market: &market
  dataset_provider: "LocalProvider"
  dataset: "csi300"
  start_time: "2008-01-01"
  end_time: "2020-08-01"
  
task:
  model:
    class: "LGBModel"
    module_path: "qlib.contrib.model.gbdt"
    kwargs:
      loss: "mse"
      colsample_bytree: 0.8879
      learning_rate: 0.0421
      subsample: 0.8789
      lambda_l1: 205.6999
      lambda_l2: 580.9768
      max_depth: 8
      num_leaves: 210
      
  dataset:
    class: "DatasetH"
    module_path: "qlib.data.dataset"
    kwargs:
      handler:
        class: "Alpha158"
        module_path: "qlib.contrib.data.handler"
        kwargs: *market
      segments:
        train: [2008-01-01, 2014-12-31]
        valid: [2015-01-01, 2016-12-31]
        test: [2017-01-01, 2020-08-01]
        
  record: 
    save_path: "benchmarks/results/LightGBM.pkl"`

// 创建配置状态管理
export const useConfigStore = create(
  persist(
    (set, get) => ({
      currentConfig: DEFAULT_CONFIG,
      configName: '默认配置',
      snapshots: [],
      isValidYaml: true,
      yamlError: null,
      
      setCurrentConfig: (config: string) => {
        const isValid = get().validateYaml(config);
        set({ 
          currentConfig: config,
          isValidYaml: isValid
        });
      },
      
      setConfigName: (name: string) => {
        set({ configName: name });
      },
      
      saveSnapshot: () => {
        const { currentConfig, configName, snapshots } = get();
        
        // 验证YAML
        if (!get().validateYaml(currentConfig)) {
          return false;
        }
        
        // 创建新快照
        const newSnapshot: ConfigSnapshot = {
          id: Date.now().toString(),
          name: configName,
          content: currentConfig,
          timestamp: Date.now()
        };
        
        // 更新快照列表
        set({ 
          snapshots: [...snapshots, newSnapshot] 
        });
        
        return true;
      },
      
      loadSnapshot: (id: string) => {
        const { snapshots } = get();
        const snapshot = snapshots.find(s => s.id === id);
        
        if (snapshot) {
          set({ 
            currentConfig: snapshot.content,
            configName: snapshot.name,
            isValidYaml: true,
            yamlError: null
          });
          return true;
        }
        
        return false;
      },
      
      deleteSnapshot: (id: string) => {
        const { snapshots } = get();
        set({ 
          snapshots: snapshots.filter(s => s.id !== id) 
        });
      },
      
      validateYaml: (content: string) => {
        try {
          YAML.parse(content);
          set({ isValidYaml: true, yamlError: null });
          return true;
        } catch (e) {
          if (e instanceof Error) {
            set({ isValidYaml: false, yamlError: e.message });
          }
          return false;
        }
      }
    }),
    {
      name: 'qlib-config-storage', // localStorage 的 key
      partialize: (state) => ({
        currentConfig: state.currentConfig,
        configName: state.configName,
        snapshots: state.snapshots
      })
    }
  )
);
