import React, { useEffect, useState, useRef } from 'react';
import { 
  Button, Card, List, Progress, Space, Tag, Typography, 
  message, Statistic, Divider, Badge, Timeline, Tabs,
  Row, Col, Alert, Descriptions, Tooltip
} from 'antd';
import {
  CheckCircleOutlined,
  CloseCircleOutlined,
  SyncOutlined,
  ClockCircleOutlined,
  SendOutlined,
  DownloadOutlined,
  InfoCircleOutlined,
  WarningOutlined,
  ReloadOutlined,
  DisconnectOutlined,
  ApiOutlined
} from '@ant-design/icons';
import WebSocketService, { MessageType, WebSocketState } from '../services/websocket';
import TaskManager, { TaskConfig, TaskManagerEvent, TaskLog } from '../services/taskManager';
import config from '../config/environment';
import PageLayout from '../components/PageLayout';

const { Title, Text, Paragraph } = Typography;
const { TabPane } = Tabs;

// 消息类型定义
interface Message {
  id: string;
  type: 'sent' | 'received' | 'system';
  content: string;
  timestamp: Date;
  messageType?: MessageType;
}

// 修改组件类型定义，使其与 React 18 兼容
const WebSocketTest = (): JSX.Element => {
  // 连接状态
  const [connected, setConnected] = useState<boolean>(false);
  const [connectionState, setConnectionState] = useState<WebSocketState | null>(null);
  const [connectionStats, setConnectionStats] = useState({
    connectedAt: null as Date | null,
    reconnectAttempts: 0,
    lastHeartbeat: null as Date | null,
    messagesSent: 0,
    messagesReceived: 0,
  });
  
  // 任务数据
  const [tasks, setTasks] = useState<any[]>([]);
  const [taskLogs, setTaskLogs] = useState<Record<string, TaskLog[]>>({});
  
  // 消息和日志
  const [logs, setLogs] = useState<string[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  
  // 自动滚动控制
  const logsEndRef = useRef<HTMLDivElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  
  // 活动任务ID
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  useEffect(() => {
    // 初始化WebSocket服务
    const ws = WebSocketService.getInstance({
      url: config.websocket.url,
      debug: true,
    });

    // 监听连接状态变化
    const unsubscribeConnection = ws.onConnectionChange((isConnected) => {
      setConnected(isConnected);
      
      if (isConnected) {
        setConnectionStats(prev => ({
          ...prev,
          connectedAt: new Date(),
        }));
        
        // 获取连接状态
        setConnectionState(ws.getState());
      } else {
        setConnectionState(WebSocketState.CLOSED);
      }
      
      addLog(`WebSocket连接状态: ${isConnected ? '已连接' : '已断开'}`);
      addMessage({
        id: `sys_${Date.now()}`,
        type: 'system',
        content: `WebSocket ${isConnected ? '已连接' : '已断开'}`,
        timestamp: new Date()
      });
    });

    // 监听消息发送和接收
    const originalSend = ws.send;
    ws.send = function(type: MessageType, payload: any) {
      setConnectionStats(prev => ({
        ...prev,
        messagesSent: prev.messagesSent + 1
      }));
      
      addMessage({
        id: `sent_${Date.now()}`,
        type: 'sent',
        content: JSON.stringify(payload, null, 2),
        timestamp: new Date(),
        messageType: type
      });
      
      return originalSend.call(ws, type, payload);
    };
    
    // 监听所有消息类型
    const messageTypes = Object.values(MessageType);
    const messageHandlers: (() => void)[] = [];
    
    messageTypes.forEach(type => {
      const handler = ws.on(type as MessageType, (payload: any) => {
        setConnectionStats(prev => ({
          ...prev,
          messagesReceived: prev.messagesReceived + 1,
          lastHeartbeat: type === MessageType.HEARTBEAT ? new Date() : prev.lastHeartbeat
        }));
        
        addMessage({
          id: `recv_${Date.now()}_${type}`,
          type: 'received',
          content: JSON.stringify(payload, null, 2),
          timestamp: new Date(),
          messageType: type as MessageType
        });
        
        // 如果是任务日志，更新任务日志
        if (type === MessageType.TASK_LOG && payload.taskId) {
          setTaskLogs(prev => {
            const logs = prev[payload.taskId] || [];
            return {
              ...prev,
              [payload.taskId]: [...logs, payload]
            };
          });
        }
      });
      
      messageHandlers.push(handler);
    });

    // 初始化任务管理器
    const taskManager = TaskManager.getInstance();

    // 监听任务添加事件
    const unsubscribeTaskAdded = taskManager.on(
      TaskManagerEvent.TASK_ADDED,
      (taskId, task) => {
        addLog(`任务已添加: ${taskId}`);
        refreshTasks();
      }
    );

    // 监听任务更新事件
    const unsubscribeTaskUpdated = taskManager.on(
      TaskManagerEvent.TASK_UPDATED,
      (taskId, task) => {
        addLog(`任务已更新: ${taskId}`);
        refreshTasks();
      }
    );

    // 监听任务完成事件
    const unsubscribeTaskCompleted = taskManager.on(
      TaskManagerEvent.TASK_COMPLETED,
      (taskId, task) => {
        addLog(`任务已完成: ${taskId}`);
        message.success(`任务 ${taskId} 已完成`);
        refreshTasks();
      }
    );

    // 监听任务失败事件
    const unsubscribeTaskFailed = taskManager.on(
      TaskManagerEvent.TASK_FAILED,
      (taskId, task) => {
        addLog(`任务已失败: ${taskId}, 原因: ${task.message || '未知错误'}`);
        message.error(`任务 ${taskId} 失败: ${task.message || '未知错误'}`);
        refreshTasks();
      }
    );

    // 连接到服务器
    ws.connect();

    // 清理函数
    return () => {
      unsubscribeConnection();
      unsubscribeTaskAdded();
      unsubscribeTaskUpdated();
      unsubscribeTaskCompleted();
      unsubscribeTaskFailed();
      
      // 清理消息处理器
      messageHandlers.forEach(handler => handler());
      
      // 断开连接
      ws.disconnect();
    };
  }, []);

  // 自动滚动到底部
  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs]);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  // 刷新任务列表
  const refreshTasks = () => {
    const taskManager = TaskManager.getInstance();
    setTasks(taskManager.getAllTasks());
  };

  // 添加日志
  const addLog = (logMessage: string) => {
    setLogs((prevLogs) => {
      const timestamp = new Date().toLocaleTimeString();
      return [`[${timestamp}] ${logMessage}`, ...prevLogs.slice(0, 99)];
    });
  };

  // 添加消息
  const addMessage = (message: Message) => {
    setMessages(prev => [...prev, message].slice(-100));
  };

  // 提交新任务
  const handleSubmitTask = async () => {
    try {
      const taskManager = TaskManager.getInstance();
      const taskConfig: TaskConfig = {
        type: 'backtest',
        config: 'yaml: test',
        name: `测试任务 ${new Date().toLocaleTimeString()}`,
        description: '这是一个测试任务',
      };

      const taskId = await taskManager.submitTask(taskConfig);
      addLog(`已提交新任务: ${taskId}`);
      message.info(`已提交新任务: ${taskId}`);
    } catch (error) {
      console.error('提交任务失败:', error);
      message.error(`提交任务失败: ${error instanceof Error ? error.message : String(error)}`);
    }
  };

  // 取消任务
  const handleCancelTask = async (taskId: string) => {
    try {
      const taskManager = TaskManager.getInstance();
      const success = await taskManager.cancelTask(taskId);
      
      if (success) {
        addLog(`已取消任务: ${taskId}`);
        message.info(`已取消任务: ${taskId}`);
      } else {
        addLog(`取消任务失败: ${taskId}`);
        message.error(`取消任务失败: ${taskId}`);
      }
    } catch (error) {
      console.error('取消任务失败:', error);
      message.error(`取消任务失败: ${error instanceof Error ? error.message : String(error)}`);
    }
  };

  // 清理已完成任务
  const handleCleanupTasks = () => {
    const taskManager = TaskManager.getInstance();
    taskManager.cleanupTasks();
    refreshTasks();
    addLog('已清理完成的任务');
  };

  // 获取任务状态标签颜色
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'pending':
        return 'default';
      case 'running':
        return 'processing';
      case 'completed':
        return 'success';
      case 'failed':
        return 'error';
      default:
        return 'default';
    }
  };

  // 获取连接状态图标
  const getConnectionStateIcon = () => {
    switch (connectionState) {
      case WebSocketState.CONNECTING:
        return <SyncOutlined spin />;
      case WebSocketState.OPEN:
        return <CheckCircleOutlined />;
      case WebSocketState.CLOSING:
        return <ClockCircleOutlined />;
      case WebSocketState.CLOSED:
        return <CloseCircleOutlined />;
      default:
        return <InfoCircleOutlined />;
    }
  };

  // 获取连接状态文本
  const getConnectionStateText = () => {
    switch (connectionState) {
      case WebSocketState.CONNECTING:
        return '正在连接';
      case WebSocketState.OPEN:
        return '已连接';
      case WebSocketState.CLOSING:
        return '正在关闭';
      case WebSocketState.CLOSED:
        return '已关闭';
      default:
        return '未知状态';
    }
  };

  // 获取消息类型标签
  const getMessageTypeTag = (type: MessageType | undefined) => {
    if (!type) return null;
    
    switch (type) {
      case MessageType.HEARTBEAT:
        return <Tag color="purple">心跳</Tag>;
      case MessageType.SYSTEM_NOTIFICATION:
        return <Tag color="blue">系统通知</Tag>;
      case MessageType.TASK_STATUS:
        return <Tag color="cyan">任务状态</Tag>;
      case MessageType.TASK_PROGRESS:
        return <Tag color="green">任务进度</Tag>;
      case MessageType.TASK_LOG:
        return <Tag color="orange">任务日志</Tag>;
      case MessageType.TASK_ERROR:
        return <Tag color="red">任务错误</Tag>;
      case MessageType.TASK_RESULT:
        return <Tag color="geekblue">任务结果</Tag>;
      case MessageType.CONFIG_UPDATE:
        return <Tag color="gold">配置更新</Tag>;
      case MessageType.CONFIG_VALIDATE:
        return <Tag color="lime">配置验证</Tag>;
      default:
        return <Tag>{type}</Tag>;
    }
  };

  return (
    <PageLayout title="WebSocket 测试">
      <div style={{ padding: 16 }}>
        <Alert
          message="WebSocket 通信测试页面"
          description="此页面用于测试 WebSocket 连接、消息收发和任务管理功能。可以查看连接状态、发送测试任务、监控消息流和查看任务日志。"
          type="info"
          showIcon
          style={{ marginBottom: 20 }}
        />

        <Row gutter={[16, 16]}>
          <Col span={24} lg={8}>
            <Card 
              title={
                <Space>
                  <ApiOutlined /> 连接状态
                  <Badge status={connected ? "success" : "error"} />
                </Space>
              } 
              style={{ marginBottom: 16 }}
            >
              <Descriptions bordered size="small" column={1}>
                <Descriptions.Item label="当前状态">
                  <Space>
                    {getConnectionStateIcon()}
                    <Text strong>{getConnectionStateText()}</Text>
                  </Space>
                </Descriptions.Item>
                <Descriptions.Item label="服务地址">
                  <Text code>{config.websocket.url}</Text>
                </Descriptions.Item>
                {connectionStats.connectedAt && (
                  <Descriptions.Item label="连接时间">
                    {connectionStats.connectedAt.toLocaleString()}
                  </Descriptions.Item>
                )}
                {connectionStats.lastHeartbeat && (
                  <Descriptions.Item label="最后心跳">
                    {connectionStats.lastHeartbeat.toLocaleString()}
                  </Descriptions.Item>
                )}
              </Descriptions>

              <Divider />

              <Row gutter={16}>
                <Col span={12}>
                  <Statistic 
                    title="已发送消息" 
                    value={connectionStats.messagesSent} 
                    prefix={<SendOutlined />} 
                  />
                </Col>
                <Col span={12}>
                  <Statistic 
                    title="已接收消息" 
                    value={connectionStats.messagesReceived} 
                    prefix={<DownloadOutlined />} 
                  />
                </Col>
              </Row>

              <Divider />

              <Space>
                <Button
                  type="primary"
                  icon={<ApiOutlined />}
                  onClick={() => WebSocketService.getInstance().connect()}
                  disabled={connected}
                >
                  连接
                </Button>
                <Button
                  danger
                  icon={<DisconnectOutlined />}
                  onClick={() => WebSocketService.getInstance().disconnect()}
                  disabled={!connected}
                >
                  断开
                </Button>
                <Tooltip title="重新连接">
                  <Button
                    icon={<ReloadOutlined />}
                    onClick={() => {
                      WebSocketService.getInstance().disconnect();
                      setTimeout(() => WebSocketService.getInstance().connect(), 500);
                    }}
                  />
                </Tooltip>
              </Space>
            </Card>

            <Card 
              title={<Space><SyncOutlined /> 任务操作</Space>} 
              style={{ marginBottom: 16 }}
            >
              <Space direction="vertical" style={{ width: '100%' }}>
                <Button 
                  type="primary" 
                  block 
                  onClick={handleSubmitTask} 
                  disabled={!connected}
                >
                  提交测试任务
                </Button>
                <Button 
                  block 
                  onClick={handleCleanupTasks}
                >
                  清理已完成任务
                </Button>
                <Button 
                  block 
                  onClick={refreshTasks}
                >
                  刷新任务列表
                </Button>
              </Space>
            </Card>
          </Col>

          <Col span={24} lg={16}>
            <Tabs defaultActiveKey="tasks" style={{ marginBottom: 16 }}>
              <TabPane 
                tab={<span><SyncOutlined /> 任务列表</span>} 
                key="tasks"
              >
                <List
                  bordered
                  dataSource={tasks}
                  renderItem={(task) => (
                    <List.Item
                      actions={[
                        task.status === 'running' ? (
                          <Button size="small" danger onClick={() => handleCancelTask(task.taskId)}>
                            取消
                          </Button>
                        ) : null,
                        <Button 
                          size="small" 
                          type="link" 
                          onClick={() => setActiveTaskId(task.taskId === activeTaskId ? null : task.taskId)}
                        >
                          {task.taskId === activeTaskId ? '收起详情' : '查看详情'}
                        </Button>
                      ].filter(Boolean)}
                    >
                      <List.Item.Meta
                        title={
                          <Space>
                            <Text strong>{task.name || task.taskId}</Text>
                            <Tag color={getStatusColor(task.status)}>{task.status}</Tag>
                          </Space>
                        }
                        description={
                          <Space direction="vertical" style={{ width: '100%' }}>
                            <Text type="secondary">{task.description || '无描述'}</Text>
                            <Progress 
                              percent={Math.round(task.progress)} 
                              status={task.status === 'failed' ? 'exception' : undefined} 
                            />
                            {task.message && <Text type="danger">{task.message}</Text>}
                            
                            {task.taskId === activeTaskId && (
                              <Card size="small" title="任务详情" style={{ marginTop: 8 }}>
                                <Descriptions size="small" column={1} bordered>
                                  <Descriptions.Item label="任务ID">{task.taskId}</Descriptions.Item>
                                  <Descriptions.Item label="类型">{task.type}</Descriptions.Item>
                                  <Descriptions.Item label="开始时间">
                                    {task.startTime ? new Date(task.startTime).toLocaleString() : '未开始'}
                                  </Descriptions.Item>
                                  {task.endTime && (
                                    <Descriptions.Item label="结束时间">
                                      {new Date(task.endTime).toLocaleString()}
                                    </Descriptions.Item>
                                  )}
                                </Descriptions>
                                
                                <Divider orientation="left">任务日志</Divider>
                                <div 
                                  style={{ 
                                    maxHeight: 200, 
                                    overflowY: 'auto',
                                    backgroundColor: '#f5f5f5',
                                    padding: 8,
                                    borderRadius: 4
                                  }}
                                >
                                  {taskLogs[task.taskId] && taskLogs[task.taskId].length > 0 ? (
                                    taskLogs[task.taskId].map((log, index) => (
                                      <div key={index} style={{ marginBottom: 4 }}>
                                        <Tag 
                                          color={
                                            log.level === 'error' ? 'red' : 
                                            log.level === 'warning' ? 'orange' : 'blue'
                                          }
                                        >
                                          {log.level}
                                        </Tag>
                                        <Text>{log.message}</Text>
                                      </div>
                                    ))
                                  ) : (
                                    <Text type="secondary">暂无日志</Text>
                                  )}
                                </div>
                              </Card>
                            )}
                          </Space>
                        }
                      />
                    </List.Item>
                  )}
                />
              </TabPane>

              <TabPane 
                tab={<span><DownloadOutlined /> 消息流</span>} 
                key="messages"
              >
                <div
                  style={{
                    height: 400,
                    overflowY: 'auto',
                    backgroundColor: '#f5f5f5',
                    padding: 10,
                    borderRadius: 4,
                  }}
                >
                  <Timeline mode="left">
                    {messages.map((msg, index) => (
                      <Timeline.Item
                        key={msg.id}
                        color={msg.type === 'sent' ? 'blue' : msg.type === 'received' ? 'green' : 'gray'}
                        label={msg.timestamp.toLocaleTimeString()}
                      >
                        <Space>
                          <Badge 
                            status={
                              msg.type === 'sent' ? 'processing' : 
                              msg.type === 'received' ? 'success' : 'default'
                            } 
                          />
                          <Text strong>
                            {msg.type === 'sent' ? '发送' : msg.type === 'received' ? '接收' : '系统'}
                          </Text>
                          {getMessageTypeTag(msg.messageType)}
                        </Space>
                        <div
                          style={{
                            backgroundColor: msg.type === 'sent' ? '#e6f7ff' : 
                                            msg.type === 'received' ? '#f6ffed' : '#f5f5f5',
                            padding: 8,
                            borderRadius: 4,
                            marginTop: 4,
                            maxHeight: 200,
                            overflowY: 'auto',
                            whiteSpace: 'pre-wrap',
                            fontFamily: 'monospace',
                            fontSize: 12
                          }}
                        >
                          {msg.content}
                        </div>
                      </Timeline.Item>
                    ))}
                    <div ref={messagesEndRef} />
                  </Timeline>
                </div>
              </TabPane>

              <TabPane 
                tab={<span><InfoCircleOutlined /> 系统日志</span>} 
                key="logs"
              >
                <div
                  style={{
                    height: 400,
                    overflowY: 'auto',
                    backgroundColor: '#f5f5f5',
                    padding: 10,
                    borderRadius: 4,
                    fontFamily: 'monospace'
                  }}
                >
                  {logs.length > 0 ? (
                    logs.map((log, index) => (
                      <div key={index} style={{ marginBottom: 4 }}>
                        {log}
                      </div>
                    ))
                  ) : (
                    <Text type="secondary">暂无日志</Text>
                  )}
                  <div ref={logsEndRef} />
                </div>
              </TabPane>
            </Tabs>
          </Col>
        </Row>
      </div>
    </PageLayout>
  );
};

export default WebSocketTest;
