import React, { useState } from 'react';
import { Layout, Menu, Button, theme } from 'antd';
import {
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  AppstoreOutlined,
  BarChartOutlined,
  SettingOutlined,
  CodeOutlined,
  DashboardOutlined,
  ApiOutlined
} from '@ant-design/icons';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';

// 页面组件导入
import Dashboard from './pages/Dashboard';
import ConfigEditor from './pages/ConfigEditor';
import TaskMonitor from './pages/TaskMonitor';
import Visualization from './pages/Visualization';
import Settings from './pages/Settings';
import WebSocketTest from './pages/WebSocketTest';

const { Header, Sider, Content } = Layout;

// 修复 React 18 类型问题
const App = (): JSX.Element => {
  const [collapsed, setCollapsed] = useState(false);
  const { token } = theme.useToken();

  // 定义菜单项
  const menuItems = [
    {
      key: 'dashboard',
      icon: <DashboardOutlined />,
      label: <Link to="/">工作台</Link>
    },
    {
      key: 'config',
      icon: <CodeOutlined />,
      label: <Link to="/config">配置编辑</Link>
    },
    {
      key: 'tasks',
      icon: <AppstoreOutlined />,
      label: <Link to="/tasks">任务监控</Link>
    },
    {
      key: 'visualization',
      icon: <BarChartOutlined />,
      label: <Link to="/visualization">数据可视化</Link>
    },
    {
      key: 'settings',
      icon: <SettingOutlined />,
      label: <Link to="/settings">系统设置</Link>
    },
    {
      key: 'websocket-test',
      icon: <ApiOutlined />,
      label: <Link to="/websocket-test">WebSocket测试</Link>
    }
  ];

  return (
    <Router>
      <Layout style={{ minHeight: '100vh' }}>
        <Header style={{
          position: 'sticky',
          top: 0,
          zIndex: 1,
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          padding: '0 16px',
          background: token.colorBgContainer
        }}>
          <div style={{ fontSize: '18px', fontWeight: 'bold', marginRight: '20px' }}>
            Qlib量化平台
          </div>
          <Button
            type="text"
            icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
            onClick={() => setCollapsed(!collapsed)}
            style={{ marginRight: '16px' }}
          />
        </Header>
        <Layout>
          <Sider width={250} collapsed={collapsed} style={{ background: token.colorBgContainer }}>
            <Menu
              mode="inline"
              defaultSelectedKeys={['dashboard']}
              style={{ height: '100%', borderRight: 0 }}
              items={menuItems}
            />
          </Sider>
          <Layout style={{ padding: '0 24px 24px' }}>
            <Content
              style={{
                padding: 24,
                margin: 0,
                minHeight: 280,
                background: token.colorBgContainer,
                borderRadius: token.borderRadiusLG,
              }}
            >
              <Routes>
                <Route path="/" element={<Dashboard />} />
                <Route path="/config" element={<ConfigEditor />} />
                <Route path="/tasks" element={<TaskMonitor />} />
                <Route path="/visualization" element={<Visualization />} />
                <Route path="/settings" element={<Settings />} />
                <Route path="/websocket-test" element={<WebSocketTest />} />
              </Routes>
            </Content>
          </Layout>
        </Layout>
      </Layout>
    </Router>
  );
};

export default App;
