import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Statistic, Button, Space, Alert, Progress, List, Typography, Tag, Empty, Spin, Tabs, Timeline } from 'antd';
import { 
  PlayCircleOutlined, 
  FileTextOutlined, 
  LineChartOutlined, 
  DatabaseOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  SyncOutlined,
  RocketOutlined,
  AreaChartOutlined,
  SettingOutlined,
  ClockCircleOutlined
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { useSettingsStore } from '../store/settingsStore';
import { useConfigStore } from '../store/configStore';
import { useTaskStore } from '../store/taskStore';
import PageLayout from '../components/PageLayout';

const { Title, Text } = Typography;
const { TabPane } = Tabs;

// 修改组件类型定义，显式指定返回类型
const Dashboard = (): JSX.Element => {
  const navigate = useNavigate();
  const { server } = useSettingsStore();
  const { configs } = useConfigStore();
  const { tasks, fetchTasks } = useTaskStore();
  
  const [isServerConnected, setIsServerConnected] = useState<boolean>(false);
  const [systemStats, setSystemStats] = useState({
    cpuUsage: 0,
    memoryUsage: 0,
    diskUsage: 0,
    uptime: 0
  });
  const [isLoading, setIsLoading] = useState<boolean>(true);
  
  // 模拟获取系统状态数据
  useEffect(() => {
    const fetchSystemStats = async () => {
      setIsLoading(true);
      
      try {
        // 实际项目中，这里应调用API获取数据
        // const response = await qlibApi.getSystemStats();
        // setSystemStats(response.data);
        
        // 模拟数据
        setTimeout(() => {
          setSystemStats({
            cpuUsage: Math.floor(Math.random() * 60) + 10,
            memoryUsage: Math.floor(Math.random() * 50) + 20,
            diskUsage: Math.floor(Math.random() * 30) + 10,
            uptime: Math.floor(Math.random() * 1000) + 100
          });
          
          setIsServerConnected(true);
          setIsLoading(false);
        }, 1000);
        
        // 模拟获取任务数据
        fetchTasks();
      } catch (error) {
        console.error('获取系统状态失败:', error);
        setIsServerConnected(false);
        setIsLoading(false);
      }
    };
    
    fetchSystemStats();
    
    // 定期刷新系统状态
    const intervalId = setInterval(fetchSystemStats, 30000);
    
    return () => clearInterval(intervalId);
  }, [fetchTasks]);
  
  // 获取最近任务
  const getRecentTasks = () => {
    return tasks.slice(0, 5).sort((a, b) => 
      new Date(b.startTime).getTime() - new Date(a.startTime).getTime()
    );
  };
  
  // 获取常用配置
  const getFrequentConfigs = () => {
    return configs
      .sort((a, b) => b.usageCount - a.usageCount)
      .slice(0, 5);
  };
  
  // 获取任务状态统计
  const getTaskStats = () => {
    const runningTasks = tasks.filter(task => task.status === 'running').length;
    const completedTasks = tasks.filter(task => task.status === 'success').length;
    const failedTasks = tasks.filter(task => task.status === 'failed').length;
    const pendingTasks = tasks.filter(task => task.status === 'pending').length;
    
    return { runningTasks, completedTasks, failedTasks, pendingTasks };
  };
  
  // 获取最近活动
  const getRecentActivities = () => {
    // 实际项目中，这里应该从API获取数据
    return [
      { id: '1', type: 'task', action: '完成', name: 'LGBM模型训练', time: '10分钟前' },
      { id: '2', type: 'config', action: '编辑', name: 'Alpha158配置', time: '30分钟前' },
      { id: '3', type: 'task', action: '开始', name: '策略回测', time: '2小时前' },
      { id: '4', type: 'system', action: '更新', name: 'Qlib库', time: '1天前' },
      { id: '5', type: 'config', action: '创建', name: '新策略配置', time: '2天前' }
    ];
  };
  
  // 格式化系统运行时间
  const formatUptime = (seconds: number) => {
    const days = Math.floor(seconds / (3600 * 24));
    const hours = Math.floor((seconds % (3600 * 24)) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    
    return `${days}天 ${hours}小时 ${minutes}分钟`;
  };
  
  // 获取活动图标
  const getActivityIcon = (type: string, action: string) => {
    if (type === 'task') {
      if (action === '完成') return <CheckCircleOutlined style={{ color: '#52c41a' }} />;
      if (action === '失败') return <CloseCircleOutlined style={{ color: '#f5222d' }} />;
      if (action === '开始') return <RocketOutlined style={{ color: '#1890ff' }} />;
    }
    if (type === 'config') {
      if (action === '编辑') return <FileTextOutlined style={{ color: '#faad14' }} />;
      if (action === '创建') return <FileTextOutlined style={{ color: '#1890ff' }} />;
    }
    if (type === 'system') {
      return <SettingOutlined style={{ color: '#722ed1' }} />;
    }
    
    return <ClockCircleOutlined style={{ color: '#d9d9d9' }} />;
  };
  
  const taskStats = getTaskStats();
  
  return (
    <PageLayout title="仪表盘">
      <div>
        <Alert
          message="自用Qlib量化平台"
          description="欢迎使用Qlib量化平台，本平台集成了配置管理、任务监控和数据可视化等功能，帮助您高效进行量化策略研究。"
          type="info"
          showIcon
          style={{ marginBottom: 24 }}
        />
        
        <Row gutter={[16, 16]}>
          {/* 快速启动卡片 */}
          <Col xs={24} sm={24} md={12} lg={8} xl={8}>
            <Card title="快速启动" bordered={false}>
              <Space direction="vertical" style={{ width: '100%' }}>
                <Button 
                  type="primary" 
                  icon={<PlayCircleOutlined />} 
                  size="large" 
                  block
                  onClick={() => navigate('/task')}
                >
                  一键执行Qlib工作流
                </Button>
                <Button 
                  icon={<FileTextOutlined />} 
                  size="large" 
                  block
                  onClick={() => navigate('/config')}
                >
                  打开配置编辑器
                </Button>
                <Button 
                  icon={<LineChartOutlined />} 
                  size="large" 
                  block
                  onClick={() => navigate('/visualization')}
                >
                  查看回测结果
                </Button>
              </Space>
            </Card>
          </Col>
          
          {/* 系统状态卡片 */}
          <Col xs={24} sm={24} md={12} lg={8} xl={8}>
            <Card title="系统状态" bordered={false}>
              {isLoading ? (
                <div style={{ textAlign: 'center', padding: '20px 0' }}>
                  <Spin />
                </div>
              ) : (
                <Row gutter={[16, 16]}>
                  <Col span={12}>
                    <Statistic 
                      title="已保存配置" 
                      value={configs.length} 
                      prefix={<FileTextOutlined />} 
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic 
                      title="运行中任务" 
                      value={taskStats.runningTasks} 
                      prefix={<SyncOutlined spin={taskStats.runningTasks > 0} />} 
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic 
                      title="已完成任务" 
                      value={taskStats.completedTasks} 
                      prefix={<CheckCircleOutlined style={{ color: '#52c41a' }} />} 
                    />
                  </Col>
                  <Col span={12}>
                    <Statistic 
                      title="失败任务" 
                      value={taskStats.failedTasks} 
                      prefix={<CloseCircleOutlined style={{ color: '#f5222d' }} />} 
                    />
                  </Col>
                  <Col span={24} style={{ marginTop: 8 }}>
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                      <div style={{ 
                        width: 8, 
                        height: 8, 
                        borderRadius: '50%', 
                        backgroundColor: isServerConnected ? '#52c41a' : '#f5222d',
                        marginRight: 8
                      }} />
                      <Text type={isServerConnected ? 'success' : 'danger'}>
                        {isServerConnected ? '服务器已连接' : '服务器未连接'}
                      </Text>
                    </div>
                  </Col>
                </Row>
              )}
            </Card>
          </Col>
          
          {/* 系统资源卡片 */}
          <Col xs={24} sm={24} md={24} lg={8} xl={8}>
            <Card title="系统资源" bordered={false}>
              {isLoading ? (
                <div style={{ textAlign: 'center', padding: '20px 0' }}>
                  <Spin />
                </div>
              ) : (
                <Space direction="vertical" style={{ width: '100%' }}>
                  <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                      <Text>CPU 使用率</Text>
                      <Text type={systemStats.cpuUsage > 80 ? 'danger' : 'secondary'}>
                        {systemStats.cpuUsage}%
                      </Text>
                    </div>
                    <Progress 
                      percent={systemStats.cpuUsage} 
                      showInfo={false} 
                      status={systemStats.cpuUsage > 80 ? 'exception' : 'normal'} 
                      size="small"
                    />
                  </div>
                  
                  <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                      <Text>内存使用率</Text>
                      <Text type={systemStats.memoryUsage > 80 ? 'danger' : 'secondary'}>
                        {systemStats.memoryUsage}%
                      </Text>
                    </div>
                    <Progress 
                      percent={systemStats.memoryUsage} 
                      showInfo={false} 
                      status={systemStats.memoryUsage > 80 ? 'exception' : 'normal'} 
                      size="small"
                    />
                  </div>
                  
                  <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                      <Text>磁盘使用率</Text>
                      <Text type={systemStats.diskUsage > 80 ? 'danger' : 'secondary'}>
                        {systemStats.diskUsage}%
                      </Text>
                    </div>
                    <Progress 
                      percent={systemStats.diskUsage} 
                      showInfo={false} 
                      status={systemStats.diskUsage > 80 ? 'exception' : 'normal'} 
                      size="small"
                    />
                  </div>
                  
                  <div style={{ marginTop: 8 }}>
                    <Text type="secondary">
                      系统运行时间: {formatUptime(systemStats.uptime)}
                    </Text>
                  </div>
                </Space>
              )}
            </Card>
          </Col>
          
          {/* 任务和配置面板 */}
          <Col span={24}>
            <Card bordered={false}>
              <Tabs defaultActiveKey="tasks">
                <TabPane 
                  tab={<span><RocketOutlined />最近任务</span>}
                  key="tasks"
                >
                  {getRecentTasks().length > 0 ? (
                    <List
                      dataSource={getRecentTasks()}
                      renderItem={task => (
                        <List.Item
                          actions={[
                            <Button 
                              type="link" 
                              onClick={() => navigate(`/task?id=${task.id}`)}
                            >
                              查看详情
                            </Button>
                          ]}
                        >
                          <List.Item.Meta
                            avatar={
                              task.status === 'running' ? <SyncOutlined spin style={{ color: '#1890ff' }} /> :
                              task.status === 'success' ? <CheckCircleOutlined style={{ color: '#52c41a' }} /> :
                              task.status === 'failed' ? <CloseCircleOutlined style={{ color: '#f5222d' }} /> :
                              <ClockCircleOutlined style={{ color: '#d9d9d9' }} />
                            }
                            title={
                              <Space>
                                <Text>{task.name}</Text>
                                <Tag color={
                                  task.type === 'training' ? 'blue' :
                                  task.type === 'backtest' ? 'green' : 'orange'
                                }>
                                  {
                                    task.type === 'training' ? '模型训练' :
                                    task.type === 'backtest' ? '策略回测' : '数据初始化'
                                  }
                                </Tag>
                              </Space>
                            }
                            description={
                              <div>
                                <Text type="secondary">
                                  {task.startTime.toLocaleString()} 
                                  {task.endTime && ` ~ ${task.endTime.toLocaleString()}`}
                                </Text>
                                {task.status === 'running' && (
                                  <Progress 
                                    percent={task.progress} 
                                    size="small" 
                                    status="active" 
                                    style={{ marginTop: 8 }}
                                  />
                                )}
                              </div>
                            }
                          />
                        </List.Item>
                      )}
                    />
                  ) : (
                    <Empty description="暂无任务记录" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                  )}
                </TabPane>
                
                <TabPane 
                  tab={<span><FileTextOutlined />常用配置</span>}
                  key="configs"
                >
                  {getFrequentConfigs().length > 0 ? (
                    <List
                      dataSource={getFrequentConfigs()}
                      renderItem={config => (
                        <List.Item
                          actions={[
                            <Button 
                              type="link" 
                              onClick={() => navigate(`/config?id=${config.id}`)}
                            >
                              编辑
                            </Button>,
                            <Button 
                              type="link" 
                              onClick={() => navigate(`/task/new?configId=${config.id}`)}
                            >
                              创建任务
                            </Button>
                          ]}
                        >
                          <List.Item.Meta
                            avatar={<FileTextOutlined />}
                            title={config.name}
                            description={
                              <div>
                                <Text type="secondary" ellipsis={{ tooltip: config.description }}>
                                  {config.description || '无描述'}
                                </Text>
                                <div style={{ marginTop: 4 }}>
                                  <Tag color="blue">{config.type}</Tag>
                                  {config.isDefault && <Tag color="gold">默认</Tag>}
                                </div>
                              </div>
                            }
                          />
                        </List.Item>
                      )}
                    />
                  ) : (
                    <Empty description="暂无配置" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                  )}
                </TabPane>
                
                <TabPane 
                  tab={<span><AreaChartOutlined />性能指标</span>}
                  key="metrics"
                >
                  {/* 这里可以根据需要显示性能指标 */}
                  <Empty description="暂无性能指标数据" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                </TabPane>
              </Tabs>
            </Card>
          </Col>
          
          {/* 最近活动卡片 */}
          <Col span={24}>
            <Card title="最近活动" bordered={false}>
              <Timeline>
                {getRecentActivities().map(activity => (
                  <Timeline.Item
                    key={activity.id}
                    dot={getActivityIcon(activity.type, activity.action)}
                  >
                    <Text strong>
                      {activity.action}了{activity.type === 'task' ? '任务' : 
                                          activity.type === 'config' ? '配置' : '系统组件'}
                    </Text>：{activity.name}
                    <div>
                      <Text type="secondary">{activity.time}</Text>
                    </div>
                  </Timeline.Item>
                ))}
              </Timeline>
            </Card>
          </Col>
        </Row>
      </div>
    </PageLayout>
  );
};

export default Dashboard;
