interface ConfigSnapshot {
  id: string;
  name: string;
  content: string;
  timestamp: number;
  comment?: string;
}

interface ModelConfig {
  name: string;
  description: string;
  params: Record<string, ModelParamConfig>;
  docLink: string;
}

interface ModelParamConfig {
  type: 'number' | 'string' | 'boolean' | 'array';
  description: string;
  default: any;
  min?: number;
  max?: number;
  options?: string[];
}

