const ConfigEditor = (): JSX.Element => {
  const [code, setCode] = React.useState(TEMPLATES.basic);
  const [configName, setConfigName] = React.useState('新配置');
  const [snapshots, setSnapshots] = React.useState<ConfigSnapshot[]>([]);
  const [yamlError, setYamlError] = React.useState<string | null>(null);
  const [editorRef, setEditorRef] = React.useState<any>(null);
  const [currentModel, setCurrentModel] = React.useState<string>('');
  const [isParameterTuningVisible, setParameterTuningVisible] = React.useState(false);
  const [isAdvancedValidationEnabled, setAdvancedValidationEnabled] = React.useState(true);
  const [activeTask, setActiveTask] = React.useState<string | null>(null);
  const [taskProgress, setTaskProgress] = React.useState<number>(0);
  const [modelParams, setModelParams] = React.useState<Record<string, any>>({});
  const [errors, setErrors] = React.useState<any[]>([]);
  const [showTemplateHelp, setShowTemplateHelp] = useState(false);
  const [previewTemplate, setPreviewTemplate] = useState('');
  const [customTemplates, setCustomTemplates] = useState<Record<string, string>>({});
  const [showTemplateManager, setShowTemplateManager] = useState<boolean>(false);
  const [templateName, setTemplateName] = useState<string>('');
  const [templateDescription, setTemplateDescription] = useState<string>('');
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [showVersionManager, setShowVersionManager] = useState<boolean>(false);
  const [versionComment, setVersionComment] = useState<string>('');
  const taskManager = React.useRef(TaskManager.getInstance());
  const ws = React.useRef(WebSocketService.getInstance());

  React.useEffect(() => {
    // 初始化WebSocket连接
    ws.current.connect();

    // 加载保存的配置和快照
    const savedConfig = localStorage.getItem('qlib_current_config');
    if (savedConfig) {
      setCode(savedConfig);
    }

    const savedSnapshots = localStorage.getItem('qlib_config_snapshots');
    if (savedSnapshots) {
      setSnapshots(JSON.parse(savedSnapshots));
    }

    // 加载自定义模板
    try {
      const savedTemplates = localStorage.getItem('qlib_custom_templates');
      if (savedTemplates) {
        setCustomTemplates(JSON.parse(savedTemplates));
      }
    } catch (e) {
      console.error('加载自定义模板失败:', e);
    }

    return () => {
      // 清理WebSocket连接
      ws.current.disconnect();
    };
  }, []);

  // 处理任务状态更新
  const handleTaskUpdate = (taskId: string) => {
    return (result: any) => {
      if (result.status === 'success') {
        message.success('任务执行成功');
        setActiveTask(null);
        setTaskProgress(100);
      } else if (result.status === 'failed') {
        message.error(`任务执行失败: ${result.error}`);
        setActiveTask(null);
      } else {
        setTaskProgress(result.data?.progress || 0);
      }
    };
  };

  // 执行任务
  const runTask = async () => {
    if (!validateYaml(code)) {
      message.error('配置格式错误，请修正后再试');
      return;
    }

    try {
      const taskId = await taskManager.current.submitTask({
        config: code,
        type: 'train'
      });

      setActiveTask(taskId);
      setTaskProgress(0);
      taskManager.current.onTaskUpdate(taskId, handleTaskUpdate(taskId));
      message.info('任务已提交');
    } catch (error) {
      message.error('提交任务失败');
      console.error(error);
    }
  };

  // 取消任务
  const cancelTask = () => {
    if (activeTask) {
      taskManager.current.cancelTask(activeTask);
      setActiveTask(null);
      setTaskProgress(0);
      message.info('任务已取消');
    }
  };

  // 在编辑器初始化完成时设置引用
  const handleEditorDidMount = (editor: any, monaco: any) => {
    setEditorRef(editor);
    
    // 设置Monaco Editor高级功能
    setupEditorFeatures(editor, monaco);
  };

  // 增强 YAML 文档结构智能提示
  const getDocumentStructure = (yamlContent: string): any => {
    try {
      return YAML.parse(yamlContent) || {};
    } catch (e) {
      // 解析失败时返回空对象
      return {};
    }
  };

  // 分析 YAML 结构，返回当前光标所在的路径上下文
  const analyzeYamlContext = (editor: any): string => {
    if (!editor) return '';
    
    const model = editor.getModel();
    const position = editor.getPosition();
    
    if (!model || !position) return '';
    
    // 获取当前行之前的所有内容
    const textUntilPosition = model.getValueInRange({
      startLineNumber: 1,
      startColumn: 1,
      endLineNumber: position.lineNumber,
      endColumn: position.column
    });
    
    // 分析缩进层级和路径
    const lines = textUntilPosition.split('\n');
    const currentLine = lines[position.lineNumber - 1] || '';
    const currentIndent = currentLine.search(/\S|$/);
    
    let path = [];
    let contextLevel = -1;
    
    // 从当前行向上分析
    for (let i = position.lineNumber - 2; i >= 0; i--) {
      const line = lines[i];
      if (!line.trim() || line.trim().startsWith('#')) continue;
      
      const indent = line.search(/\S|$/);
      if (indent < currentIndent) {
        // 找到上一级缩进
        const match = line.trim().match(/^([^:]+):/);
        if (match) {
          path.unshift(match[1].trim());
          contextLevel = indent;
          
          // 如果已经到达顶层，则停止
          if (indent === 0) break;
        }
      }
    }
    
    return path.join('.');
  };

  // YAML 结构定义，用于智能提示
  const YAML_SCHEMA = {
    qlib_init: {
      provider_uri: { type: 'string', description: '数据提供者URI路径' },
      region: { type: 'string', description: '地区代码，如cn、us等' },
      logging_level: { type: 'string', description: '日志级别，如INFO、DEBUG、WARNING、ERROR' },
      exp_manager: { type: 'object', description: '实验管理器配置' }
    },
    market: {
      dataset_provider: { type: 'string', description: '数据集提供者类型' },
      dataset: { type: 'string', description: '数据集名称' },
      start_time: { type: 'string', description: '开始时间，格式：YYYY-MM-DD' },
      end_time: { type: 'string', description: '结束时间，格式：YYYY-MM-DD' },
      instruments: { type: 'string', description: '股票代码列表或过滤条件' }
    },
    task: {
      model: {
        class: { type: 'string', description: '模型类名' },
        module_path: { type: 'string', description: '模型模块路径' },
        kwargs: { type: 'object', description: '模型参数' }
      },
      dataset: {
        class: { type: 'string', description: '数据集类名' },
        module_path: { type: 'string', description: '数据集模块路径' },
        kwargs: { type: 'object', description: '数据集参数' },
        segments: { type: 'object', description: '数据集分段' }
      },
      record: {
        save_path: { type: 'string', description: '结果保存路径' },
        metrics: { type: 'array', description: '评估指标列表' }
      },
      tuner: {
        class: { type: 'string', description: '调优器类名' },
        module_path: { type: 'string', description: '调优器模块路径' },
        kwargs: { type: 'object', description: '调优器参数' }
      }
    }
  };

  // 常用模型类型
  const MODEL_CLASSES = [
    { label: 'LGBModel', detail: 'LightGBM模型', documentation: '基于树的梯度提升框架，高效、分布式、GPU支持' },
    { label: 'XGBModel', detail: 'XGBoost模型', documentation: '高效、灵活且可移植的分布式梯度提升库' },
    { label: 'LinearModel', detail: '线性模型', documentation: '基础线性回归/分类模型' },
    { label: 'MLP', detail: '多层感知机', documentation: '基础神经网络模型' },
    { label: 'LSTM', detail: '长短期记忆网络', documentation: '用于序列数据的循环神经网络' },
    { label: 'GRU', detail: '门控循环单元', documentation: 'LSTM的变体，计算效率更高' },
    { label: 'GATs', detail: '图注意力网络', documentation: '用于图数据的神经网络' },
    { label: 'TFT', detail: '时间融合Transformer', documentation: '用于时间序列预测的Transformer模型' }
  ];

  // 常用数据集类型
  const DATASET_CLASSES = [
    { label: 'DatasetH', detail: '分层数据集', documentation: 'Qlib标准分层数据集结构' },
    { label: 'TSDatasetH', detail: '时间序列数据集', documentation: '用于时间序列预测的数据集' },
    { label: 'DatasetProvider', detail: '数据集提供者', documentation: '通用数据集提供接口' }
  ];

  // 常用数据处理器
  const HANDLER_CLASSES = [
    { label: 'Alpha158', detail: '158个Alpha因子', documentation: 'Qlib预定义的158个Alpha因子特征' },
    { label: 'Alpha360', detail: '360个Alpha因子', documentation: 'Qlib预定义的360个Alpha因子特征' },
    { label: 'Alpha101', detail: '101个Alpha因子', documentation: '经典的101个Alpha因子特征' },
    { label: 'HighFreqHandler', detail: '高频数据处理器', documentation: '用于处理高频数据的特征提取器' }
  ];

  // 设置编辑器高级功能
  const setupEditorFeatures = (editor: any, monaco: any) => {
    if (!editor || !monaco) return;
    
    // 注册自动补全提供者
    monaco.languages.registerCompletionItemProvider('yaml', {
      provideCompletionItems: (model: any, position: any) => {
        const textUntilPosition = model.getValueInRange({
          startLineNumber: 1,
          startColumn: 1,
          endLineNumber: position.lineNumber,
          endColumn: position.column
        });
        
        // 获取当前上下文路径
        const contextPath = analyzeYamlContext(editor);
        const lineContent = model.getLineContent(position.lineNumber);
        const linePrefix = lineContent.substring(0, position.column - 1).trim();
        
        // 创建建议项
        const suggestions = [];
        
        // 根据上下文提供不同的建议
        if (contextPath.includes('model.class') || linePrefix.endsWith('class:')) {
          // 模型类建议
          MODEL_CLASSES.forEach(model => {
            suggestions.push({
              label: model.label,
              kind: monaco.languages.CompletionItemKind.Class,
              detail: model.detail,
              documentation: model.documentation,
              insertText: model.label
            });
          });
        } else if (contextPath.includes('dataset.class') || linePrefix.endsWith('dataset.class:')) {
          // 数据集类建议
          DATASET_CLASSES.forEach(dataset => {
            suggestions.push({
              label: dataset.label,
              kind: monaco.languages.CompletionItemKind.Class,
              detail: dataset.detail,
              documentation: dataset.documentation,
              insertText: dataset.label
            });
          });
        } else if (contextPath.includes('handler.class') || linePrefix.endsWith('handler.class:')) {
          // 处理器类建议
          HANDLER_CLASSES.forEach(handler => {
            suggestions.push({
              label: handler.label,
              kind: monaco.languages.CompletionItemKind.Class,
              detail: handler.detail,
              documentation: handler.documentation,
              insertText: handler.label
            });
          });
        } else if (linePrefix.endsWith(':')) {
          // 基于缩进和上下文的建议
          const pathParts = contextPath.split('.');
          let schema = YAML_SCHEMA;
          
          // 遍历路径，找到对应的模式
          for (const part of pathParts) {
            if (schema[part]) {
              schema = schema[part];
            } else {
              break;
            }
          }
          
          // 添加建议
          Object.keys(schema).forEach(key => {
            const item = schema[key];
            suggestions.push({
              label: key,
              kind: monaco.languages.CompletionItemKind.Property,
              detail: item.type,
              documentation: item.description,
              insertText: `${key}: `
            });
          });
        }
        
        return { suggestions };
      }
    });
    
    // 添加YAML验证
    const yamlContent = editor.getValue();
    validateYaml(yamlContent);
    
    // 添加变更监听
    editor.onDidChangeModelContent(() => {
      const newContent = editor.getValue();
      validateYaml(newContent);
    });
  };

  // 高级YAML验证
  const validateYaml = (yamlContent: string): boolean => {
    try {
      // 基本语法验证
      const parsedYaml = YAML.parse(yamlContent);
      setYamlError(null);
      
      // 高级验证
      const validationError = performAdvancedValidation(parsedYaml);
      if (validationError) {
        setErrors([{ message: validationError }]);
        return false;
      }
      
      setErrors([]);
      return true;
    } catch (e) {
      if (e instanceof Error) {
        setYamlError(e.message);
      } else {
        setYamlError('未知YAML解析错误');
      }
      return false;
    }
  };

  // 执行高级验证
  const performAdvancedValidation = (config: any): string | null => {
    if (!config) return '配置不能为空';
    
    // 验证必要字段
    if (!config.task) {
      return '缺少必要的task配置部分';
    }
    
    // 验证模型配置
    if (config.task.model) {
      const model = config.task.model;
      if (!model.class) {
        return 'task.model缺少必要的class字段';
      }
      if (!model.module_path) {
        return 'task.model缺少必要的module_path字段';
      }
      
      // 验证模型类型
      const validModelClasses = MODEL_CLASSES.map(m => m.label);
      if (!validModelClasses.includes(model.class)) {
        return `不支持的模型类型: ${model.class}。支持的类型: ${validModelClasses.join(', ')}`;
      }
      
      // 验证模型参数
      if (model.class === 'LGBModel' && model.kwargs) {
        // LightGBM特定验证
        const { learning_rate, max_depth, num_leaves } = model.kwargs;
        
        if (learning_rate && (learning_rate < 0.001 || learning_rate > 1)) {
          return 'learning_rate应在0.001到1之间';
        }
        
        if (max_depth && max_depth < 3 && max_depth !== -1) {
          return 'max_depth应大于等于3或设为-1(无限制)';
        }
        
        if (num_leaves && (num_leaves < 2 || num_leaves > 1000)) {
          return 'num_leaves应在2到1000之间';
        }
      }
    } else {
      return '缺少必要的task.model配置部分';
    }
    
    // 验证数据集配置
    if (config.task.dataset) {
      const dataset = config.task.dataset;
      if (!dataset.class) {
        return 'task.dataset缺少必要的class字段';
      }
      
      // 验证数据集分段
      if (dataset.segments) {
        const { train, valid, test } = dataset.segments;
        if (!train) {
          return 'dataset.segments缺少必要的train分段';
        }
        
        // 验证日期格式和顺序
        const validateDateRange = (range: any): boolean => {
          if (!Array.isArray(range) || range.length !== 2) return false;
          
          // 简单日期格式验证
          const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
          return dateRegex.test(range[0]) && dateRegex.test(range[1]);
        };
        
        if (!validateDateRange(train)) {
          return 'train日期范围格式错误，应为[YYYY-MM-DD, YYYY-MM-DD]';
        }
        
        if (valid && !validateDateRange(valid)) {
          return 'valid日期范围格式错误，应为[YYYY-MM-DD, YYYY-MM-DD]';
        }
        
        if (test && !validateDateRange(test)) {
          return 'test日期范围格式错误，应为[YYYY-MM-DD, YYYY-MM-DD]';
        }
      } else {
        return 'task.dataset缺少必要的segments配置';
      }
    } else {
      return '缺少必要的task.dataset配置部分';
    }
    
    return null;
  };

  // 打开参数调优工具
  const openParameterTuning = () => {
    // 分析当前YAML内容，提取模型参数
    try {
      const parsed = YAML.parse(code);
      if (parsed?.task?.model?.class && MODEL_CONFIGS[parsed.task.model.class]) {
        setCurrentModel(parsed.task.model.class);
        setModelParams(parsed.task.model.kwargs || {});
        setParameterTuningVisible(true);
      } else {
        message.warning('请先在配置中指定有效的模型类');
      }
    } catch (e) {
      message.error('无法解析当前配置，请先修复YAML格式错误');
    }
  };

  // 处理参数调优表单提交
  const handleParameterTuningSubmit = (values: any) => {
    setModelParams(values);
    try {
      const config = YAML.parse(code);
      if (config?.task?.model?.kwargs) {
        config.task.model.kwargs = { ...config.task.model.kwargs, ...values };
        const newCode = YAML.stringify(config);
        setCode(newCode);
        message.success('参数已更新');
      }
    } catch (e) {
      message.error('更新参数失败');
      console.error(e);
    }
    setParameterTuningVisible(false);
  };

  // 渲染参数调优表单
  const renderParameterTuningForm = () => {
    const modelConfig = MODEL_CONFIGS[currentModel];
    if (!modelConfig) {
      return <div>请先选择模型类型</div>;
    }

    return (
      <Form
        layout="vertical"
        onFinish={handleParameterTuningSubmit}
        initialValues={modelParams}
      >
        {Object.entries(modelConfig.params).map(([paramName, paramConfig]) => {
          if (paramConfig.type === 'number') {
            return (
              <Form.Item 
                key={paramName}
                name={paramName}
                label={
                  <span>
                    {paramName} 
                    <Tooltip title={paramConfig.description}>
                      <QuestionCircleOutlined style={{ marginLeft: 8 }} />
                    </Tooltip>
                  </span>
                }
              >
                <Input 
                  type="number" 
                  step="0.01"
                  min={paramConfig.min}
                  max={paramConfig.max}
                />
              </Form.Item>
            );
          }
          
          if (paramConfig.type === 'string' && paramConfig.options) {
            return (
              <Form.Item 
                key={paramName}
                name={paramName}
                label={
                  <span>
                    {paramName} 
                    <Tooltip title={paramConfig.description}>
                      <QuestionCircleOutlined style={{ marginLeft: 8 }} />
                    </Tooltip>
                  </span>
                }
              >
                <Select>
                  {paramConfig.options.map(option => (
                    <Select.Option key={option} value={option}>
                      {option}
                    </Select.Option>
                  ))}
                </Select>
              </Form.Item>
            );
          }
          
          return (
            <Form.Item 
              key={paramName}
              name={paramName}
              label={
                <span>
                  {paramName} 
                  <Tooltip title={paramConfig.description}>
                    <QuestionCircleOutlined style={{ marginLeft: 8 }} />
                  </Tooltip>
                </span>
              }
            >
              <Input />
            </Form.Item>
          );
        })}
        
        <Form.Item>
          <Button type="primary" htmlType="submit">
            应用参数
          </Button>
        </Form.Item>
      </Form>
    );
  };

  // 在Monaco Editor配置中添加YAML语言支持
  const handleEditorWillMount = (monaco: any) => {
    monaco.languages.register({ id: 'yaml' });
    monaco.languages.setMonarchTokensProvider('yaml', {
      // YAML语法高亮规则
      tokenizer: {
        root: [
          [/---/, 'delimiter.yaml'],
          [/\.\.\./, 'delimiter.yaml'],
          [/#.*$/, 'comment'],
          [/('''|""")/, 'string', '@endDocString'],
          [/'[^']*'/, 'string'],
          [/"[^"]*"/, 'string'],
          [/\b(true|false|null)\b/, 'constant'],
          [/\d+/, 'number'],
          [/:/, 'delimiter'],
          [/\w+/, {
            cases: {
              '@keywords': 'keyword',
              '@default': 'identifier'
            }
          }]
        ],
        endDocString: [
          [/([^\\]|\\.)'''/, 'string', '@pop'],
          [/([^\\]|\\.)"""/, 'string', '@pop']
        ]
      },
      keywords: ['true', 'false', 'null']
    });

    // 添加YAML schema校验
    monaco.languages.yaml.yamlDefaults.setDiagnosticsOptions({
      validate: true,
      schemas: [{
        uri: 'qlib-schema.json',
        fileMatch: ['*'],
        schema: {
          type: 'object',
          properties: {
            qlib_init: {
              type: 'object',
              required: ['provider_uri', 'region']
            },
            task: {
              type: 'object',
              properties: {
                model: {
                  type: 'object',
                  required: ['class', 'module_path']
                }
              }
            }
          }
        }
      }]
    });
  };

  // 添加模板管理相关函数
  const saveAsTemplate = () => {
    if (!templateName.trim()) {
      message.error('模板名称不能为空');
      return;
    }

    if (!validateYaml(code)) {
      message.error('当前配置存在YAML语法错误，无法保存为模板');
      return;
    }

    try {
      const newTemplates = { ...customTemplates };
      newTemplates[templateName] = code;
      
      // 保存到localStorage
      localStorage.setItem('qlib_custom_templates', JSON.stringify(newTemplates));
      setCustomTemplates(newTemplates);
      
      // 重置表单并关闭对话框
      setTemplateName('');
      setTemplateDescription('');
      setShowTemplateManager(false);
      
      message.success(`已将当前配置保存为模板: ${templateName}`);
    } catch (e) {
      message.error('保存模板失败');
      console.error(e);
    }
  };

  const deleteTemplate = (name: string) => {
    try {
      const newTemplates = { ...customTemplates };
      delete newTemplates[name];
      
      // 保存到localStorage
      localStorage.setItem('qlib_custom_templates', JSON.stringify(newTemplates));
      setCustomTemplates(newTemplates);
      
      message.success(`已删除模板: ${name}`);
    } catch (e) {
      message.error('删除模板失败');
      console.error(e);
    }
  };

  const loadTemplate = (name: string) => {
    try {
      const templateContent = customTemplates[name] || TEMPLATES[name];
      if (templateContent) {
        setCode(templateContent);
        validateYaml(templateContent);
        message.success(`已加载模板: ${name}`);
      }
    } catch (e) {
      message.error('加载模板失败');
      console.error(e);
    }
  };

  // 添加版本管理相关函数
  const createVersionSnapshot = (comment: string = '') => {
    if (!validateYaml(code)) {
      message.error('当前配置存在YAML语法错误，无法创建版本');
      return;
    }

    try {
      const newSnapshot: ConfigSnapshot = {
        id: Date.now().toString(),
        name: configName,
        content: code,
        timestamp: Date.now(),
        comment: comment || `版本 ${snapshots.length + 1}`
      };
      
      const newSnapshots = [...snapshots, newSnapshot];
      setSnapshots(newSnapshots);
      
      // 保存到localStorage
      localStorage.setItem(`qlib_config_snapshots_${configName}`, JSON.stringify(newSnapshots));
      
      message.success('已创建新版本');
      return true;
    } catch (e) {
      message.error('创建版本失败');
      console.error(e);
      return false;
    }
  };

  const loadVersionSnapshot = (id: string) => {
    try {
      const snapshot = snapshots.find(s => s.id === id);
      if (snapshot) {
        setCode(snapshot.content);
        validateYaml(snapshot.content);
        message.success(`已恢复到版本: ${snapshot.comment || snapshot.name}`);
        return true;
      }
      return false;
    } catch (e) {
      message.error('加载版本失败');
      console.error(e);
      return false;
    }
  };

  const deleteVersionSnapshot = (id: string) => {
    try {
      const newSnapshots = snapshots.filter(s => s.id !== id);
      setSnapshots(newSnapshots);
      
      // 保存到localStorage
      localStorage.setItem(`qlib_config_snapshots_${configName}`, JSON.stringify(newSnapshots));
      
      message.success('已删除版本');
      return true;
    } catch (e) {
      message.error('删除版本失败');
      console.error(e);
      return false;
    }
  };

  // 在组件内部添加模板管理器对话框
  const renderTemplateManager = () => {
    return (
      <Modal
        title="模板管理"
        open={showTemplateManager}
        onCancel={() => setShowTemplateManager(false)}
        footer={null}
        width={800}
      >
        <Tabs defaultActiveKey="save">
          <TabPane tab="保存为模板" key="save">
            <Form layout="vertical">
              <Form.Item 
                label="模板名称" 
                required
                help="给你的模板起一个有意义的名称"
              >
                <Input 
                  value={templateName} 
                  onChange={e => setTemplateName(e.target.value)} 
                  placeholder="例如：LightGBM基础模型"
                />
              </Form.Item>
              <Form.Item 
                label="模板描述"
                help="简要描述这个模板的用途和特点"
              >
                <Input.TextArea 
                  value={templateDescription} 
                  onChange={e => setTemplateDescription(e.target.value)} 
                  placeholder="例如：用于股票预测的LightGBM基础配置"
                  rows={4}
                />
              </Form.Item>
              <Form.Item>
                <Button type="primary" onClick={saveAsTemplate}>
                  保存模板
                </Button>
              </Form.Item>
            </Form>
          </TabPane>
          <TabPane tab="模板列表" key="list">
            <Tabs defaultActiveKey="custom">
              <TabPane tab="自定义模板" key="custom">
                {Object.keys(customTemplates).length > 0 ? (
                  <List
                    dataSource={Object.keys(customTemplates)}
                    renderItem={name => (
                      <List.Item
                        actions={[
                          <Button 
                            type="link" 
                            onClick={() => loadTemplate(name)}
                          >
                            加载
                          </Button>,
                          <Popconfirm
                            title="确定要删除此模板吗?"
                            onConfirm={() => deleteTemplate(name)}
                            okText="确定"
                            cancelText="取消"
                          >
                            <Button type="link" danger>
                              删除
                            </Button>
                          </Popconfirm>
                        ]}
                      >
                        <List.Item.Meta
                          title={name}
                          description={<Typography.Text code ellipsis>{customTemplates[name].substring(0, 100)}...</Typography.Text>}
                        />
                      </List.Item>
                    )}
                  />
                ) : (
                  <Empty description="暂无自定义模板" />
                )}
              </TabPane>
              <TabPane tab="内置模板" key="builtin">
                <List
                  dataSource={Object.keys(TEMPLATES)}
                  renderItem={name => (
                    <List.Item
                      actions={[
                        <Button 
                          type="link" 
                          onClick={() => loadTemplate(name)}
                        >
                          加载
                        </Button>,
                        <Button 
                          type="link" 
                          onClick={() => {
                            setSelectedTemplate(name);
                          }}
                        >
                          预览
                        </Button>
                      ]}
                    >
                      <List.Item.Meta
                        title={name}
                        description={<Typography.Text code ellipsis>{TEMPLATES[name].substring(0, 100)}...</Typography.Text>}
                      />
                    </List.Item>
                  )}
                />
              </TabPane>
            </Tabs>
          </TabPane>
        </Tabs>
      </Modal>
    );
  };

  // 在组件内部添加版本管理对话框
  const renderVersionManager = () => {
    return (
      <Modal
        title="版本管理"
        open={showVersionManager}
        onCancel={() => setShowVersionManager(false)}
        footer={null}
        width={800}
      >
        <Tabs defaultActiveKey="create">
          <TabPane tab="创建新版本" key="create">
            <Form layout="vertical">
              <Form.Item 
                label="版本备注" 
                help="添加描述以便于识别此版本的变更内容"
              >
                <Input.TextArea 
                  value={versionComment} 
                  onChange={e => setVersionComment(e.target.value)} 
                  placeholder="例如：调整学习率参数"
                  rows={4}
                />
              </Form.Item>
              <Form.Item>
                <Button 
                  type="primary" 
                  onClick={() => {
                    if (createVersionSnapshot(versionComment)) {
                      setVersionComment('');
                      setShowVersionManager(false);
                    }
                  }}
                >
                  创建版本
                </Button>
              </Form.Item>
            </Form>
          </TabPane>
          <TabPane tab="版本历史" key="history">
            {snapshots.length > 0 ? (
              <List
                dataSource={[...snapshots].reverse()}
                renderItem={snapshot => (
                  <List.Item
                    actions={[
                      <Button 
                        type="link" 
                        onClick={() => loadVersionSnapshot(snapshot.id)}
                      >
                        恢复
                      </Button>,
                      <Popconfirm
                        title="确定要删除此版本吗?"
                        onConfirm={() => deleteVersionSnapshot(snapshot.id)}
                        okText="确定"
                        cancelText="取消"
                      >
                        <Button type="link" danger>
                          删除
                        </Button>
                      </Popconfirm>
                    ]}
                  >
                    <List.Item.Meta
                      title={
                        <Space>
                          <span>{snapshot.comment || `版本 ${snapshots.indexOf(snapshot) + 1}`}</span>
                          <Tag color="blue">{new Date(snapshot.timestamp).toLocaleString()}</Tag>
                        </Space>
                      }
                      description={<Typography.Text code ellipsis>{snapshot.content.substring(0, 100)}...</Typography.Text>}
                    />
                  </List.Item>
                )}
              />
            ) : (
              <Empty description="暂无版本历史" />
            )}
          </TabPane>
        </Tabs>
      </Modal>
    );
  };

  return (
    <div>
      <Card title="Qlib配置编辑器" bordered={false}>
        <Row gutter={16} style={{ marginBottom: 16 }}>
          <Col span={24}>
            <Card size="small">
              <Space>
                <Select
                  style={{ width: 200 }}
                  placeholder="选择配置模板"
                  onChange={(value) => {
                    setCode(TEMPLATES[value]);
                    message.success(`已加载${value}模板`);
                  }}
                >
                  {Object.keys(TEMPLATES).map(key => (
                    <Select.Option key={key} value={key}>
                      <Tooltip title={TEMPLATES[key].substring(0, 100) + '...'}>
                        {key}
                      </Tooltip>
                    </Select.Option>
                  ))}
                </Select>
                <Button 
                  icon={<QuestionCircleOutlined />} 
                  onClick={() => setShowTemplateHelp(true)}
                >
                  模板说明
                </Button>
              </Space>
            </Card>
          </Col>
        </Row>
        <Row gutter={[16, 16]}>
          <Col span={24} style={{ marginBottom: 16 }}>
            <Space>
              <Button 
                type="primary" 
                icon={<SaveOutlined />} 
                onClick={() => {
                  if (!validateYaml(code)) {
                    message.error('YAML格式错误，请修正后再保存');
                    return;
                  }
                  
                  localStorage.setItem('qlib_current_config', code);
                  
                  // 创建新快照
                  const newSnapshot: ConfigSnapshot = {
                    id: Date.now().toString(),
                    name: configName,
                    content: code,
                    timestamp: Date.now()
                  };
                  
                  const updatedSnapshots = [...snapshots, newSnapshot];
                  setSnapshots(updatedSnapshots);
                  localStorage.setItem('qlib_config_snapshots', JSON.stringify(updatedSnapshots));
                  
                  message.success('配置已保存');
                }}
              >
                保存配置
              </Button>
              <Button 
                icon={<PlayCircleOutlined />}
                onClick={runTask}
                disabled={!!activeTask}
                loading={!!activeTask}
              >
                {activeTask ? '执行中' : '立即运行'}
              </Button>
              {activeTask && (
                <Button
                  icon={<StopOutlined />}
                  onClick={cancelTask}
                  danger
                >
                  取消任务
                </Button>
              )}
              <Select
                style={{ width: 180 }}
                placeholder="选择模板"
                onChange={(template: string) => setCode(TEMPLATES[template as keyof typeof TEMPLATES])}
              >
                <Select.Option value="basic">基础配置模板</Select.Option>
                <Select.Option value="lgbm_tuning">LGBM调参模板</Select.Option>
              </Select>
              <Button 
                icon={<DownloadOutlined />} 
                onClick={() => {
                  const blob = new Blob([code], { type: 'text/yaml' });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement('a');
                  a.href = url;
                  a.download = `${configName.replace(/\s+/g, '_')}.yaml`;
                  document.body.appendChild(a);
                  a.click();
                  document.body.removeChild(a);
                  URL.revokeObjectURL(url);
                }}
              >
                导出配置
              </Button>
              <Button
                icon={<SettingOutlined />}
                onClick={openParameterTuning}
              >
                参数调优助手
              </Button>
              <Button
                icon={<FileTextOutlined />}
                onClick={() => {
                  try {
                    const configObj = YAML.parse(code);
                    if (!configObj) {
                      message.error('无法解析当前YAML内容');
                      return;
                    }
                    
                    // 保存为模板
                    const templateName = `自定义模板_${new Date().toISOString().slice(0, 10)}`;
                    let templates = JSON.parse(localStorage.getItem('qlib_custom_templates') || '{}');
                    templates[templateName] = code;
                    localStorage.setItem('qlib_custom_templates', JSON.stringify(templates));
                    
                    message.success(`已将当前配置保存为模板: ${templateName}`);
                  } catch (e) {
                    message.error('保存模板失败');
                    console.error(e);
                  }
                }}
              >
                导出为模板
              </Button>
              <Button
                icon={<FileTextOutlined />}
                onClick={() => setShowTemplateManager(true)}
              >
                模板管理
              </Button>
              <Button
                icon={<HistoryOutlined />}
                onClick={() => setShowVersionManager(true)}
              >
                版本管理
              </Button>
            </Space>
            
            <div style={{ float: 'right' }}>
              {activeTask && (
                <div style={{ display: 'inline-block', marginRight: 16 }}>
                  <Progress type="circle" percent={taskProgress} width={32} />
                </div>
              )}
              <Tooltip title={isAdvancedValidationEnabled ? '已启用配置高级验证' : '已禁用配置高级验证'}>
                <Tag 
                  color={isAdvancedValidationEnabled ? 'green' : 'orange'}
                  style={{ cursor: 'pointer' }}
                  onClick={() => setAdvancedValidationEnabled(!isAdvancedValidationEnabled)}
                >
                  高级验证: {isAdvancedValidationEnabled ? '开启' : '关闭'}
                </Tag>
              </Tooltip>
            </div>
          </Col>
          
          <Col span={24}>
            <Tabs defaultActiveKey="editor">
              <TabPane tab="编辑器" key="editor">
                <div className="monaco-editor-container">
                  <MonacoEditor
                    height="600px"
                    language="yaml"
                    theme="vs-light"
                    value={code}
                    onChange={(value: string | undefined) => {
                      if (value) {
                        setCode(value);
                        validateYaml(value);
                      }
                    }}
                    beforeMount={handleEditorWillMount}
                    onMount={handleEditorDidMount}
                    onValidate={(markers) => {
                      setErrors(markers.filter(m => m.severity > 3));
                    }}
                    options={{
                      minimap: { enabled: true },
                      fontSize: 14,
                      scrollBeyondLastLine: false,
                      automaticLayout: true,
                    }}
                  />
                </div>
                {yamlError && (
                  <div style={{ color: 'red', marginTop: 8 }}>
                    错误: {yamlError}
                  </div>
                )}
                {errors.length > 0 && (
                  <div style={{ color: 'red', marginTop: 8 }}>
                    {errors.map((error, index) => (
                      <div key={index}>
                        {error.message}
                      </div>
                    ))}
                  </div>
                )}
              </TabPane>
              <TabPane tab="历史版本" key="history">
                {snapshots.length > 0 ? (
                  <div style={{ maxHeight: '600px', overflow: 'auto' }}>
                    {snapshots.map((snapshot: ConfigSnapshot) => (
                      <Card 
                        key={snapshot.id}
                        size="small" 
                        style={{ marginBottom: 8 }}
                        actions={[
                          <Tooltip title="加载此版本" key="load">
                            <Button 
                              type="text" 
                              icon={<FileTextOutlined />} 
                              onClick={() => {
                                setCode(snapshot.content);
                                setConfigName(snapshot.name);
                                message.success(`已加载快照: ${snapshot.name}`);
                              }}
                            />
                          </Tooltip>,
                          <Tooltip title="复制" key="copy">
                            <Button 
                              type="text" 
                              icon={<CopyOutlined />} 
                              onClick={() => {
                                navigator.clipboard.writeText(snapshot.content).then(() => {
                                  message.success('已复制到剪贴板');
                                }).catch((err) => {
                                  console.error('复制到剪贴板失败:', err);
                                  message.error('复制失败，请手动选择并复制内容');
                                });
                              }}
                            />
                          </Tooltip>
                        ]}
                      >
                        <div>
                          <strong>{snapshot.name}</strong>
                          <div style={{ fontSize: 12, color: '#888' }}>
                            保存时间: {new Date(snapshot.timestamp).toLocaleString()}
                          </div>
                        </div>
                      </Card>
                    ))}
                  </div>
                ) : (
                  <div style={{ textAlign: 'center', padding: 24 }}>
                    <HistoryOutlined style={{ fontSize: 32, color: '#ccc' }} />
                    <p>暂无历史版本记录</p>
                  </div>
                )}
              </TabPane>
            </Tabs>
          </Col>
        </Row>
      </Card>
      
      <Modal
        title="模板预览"
        width={800}
        visible={showTemplateHelp}
        onCancel={() => setShowTemplateHelp(false)}
        footer={null}
      >
        <Tabs defaultActiveKey="basic">
          {Object.keys(TEMPLATES).map(key => (
            <Tabs.TabPane tab={key} key={key}>
              <MonacoEditor
                height="400px"
                language="yaml"
                value={TEMPLATES[key]}
                options={{
                  readOnly: true,
                  minimap: { enabled: false },
                  scrollBeyondLastLine: false
                }}
              />
            </Tabs.TabPane>
          ))}
        </Tabs>
      </Modal>
      
      <Modal
        title="参数调优"
        open={isParameterTuningVisible}
        onCancel={() => setParameterTuningVisible(false)}
        footer={null}
      >
        {renderParameterTuningForm()}
      </Modal>
      
      {renderTemplateManager()}
      {renderVersionManager()}
    </div>
  );
};

export default ConfigEditor;
